-- ============================================================================
-- ReturnFlow - PostgreSQL schema (Phase 2)
-- Run against an empty `returnflow` database. Tables are created in
-- dependency order, so there are no foreign-key ordering errors.
--
-- Conventions
--   * ids:    INTEGER GENERATED BY DEFAULT AS IDENTITY
--   * times:  TIMESTAMPTZ everywhere
--   * money:  NUMERIC(12,2), never floating point
--   * enums:  TEXT + CHECK constraints (easy to evolve with ALTER TABLE)
--   * deletes: ON DELETE RESTRICT on business records, so history is preserved
-- ============================================================================


-- ----------------------------------------------------------------------------
-- Shared trigger: keep updated_at current on every UPDATE
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;


-- ----------------------------------------------------------------------------
-- 1. users  (all four roles live here; one authentication system)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name          TEXT        NOT NULL,
    email         TEXT        NOT NULL,
    password_hash TEXT        NOT NULL,           -- bcrypt hash, never plaintext
    role          TEXT        NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT users_role_check
        CHECK (role IN ('CUSTOMER', 'SELLER', 'PICKUP_AGENT', 'WAREHOUSE', 'ADMIN'))
);

-- Databases created before the ADMIN role existed: widen the constraint (safe to re-run, no data touched)
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;
ALTER TABLE users ADD CONSTRAINT users_role_check
    CHECK (role IN ('CUSTOMER', 'SELLER', 'PICKUP_AGENT', 'WAREHOUSE', 'ADMIN'));

-- Case-insensitive uniqueness: Alice@x.com and alice@x.com are the same user
CREATE UNIQUE INDEX IF NOT EXISTS users_email_unique_idx ON users (LOWER(email));
CREATE INDEX IF NOT EXISTS users_role_idx ON users (role);


-- ----------------------------------------------------------------------------
-- 2. products
-- Only SELLER users should own products; that rule is enforced in the service
-- layer (a CHECK cannot look at another table).
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS products (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    seller_id   INTEGER       NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    name        TEXT          NOT NULL,
    description TEXT,
    price       NUMERIC(12,2) NOT NULL,
    image_url   TEXT,                              -- reference image for AI inspection
    created_at  TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ   NOT NULL DEFAULT NOW(),

    CONSTRAINT products_price_check CHECK (price >= 0)
);

CREATE INDEX IF NOT EXISTS products_seller_id_idx ON products (seller_id);

-- Reference to the product's original image in the PRIVATE S3 bucket (object key only: no URL, no bytes).
-- Added later, so this is a safe ALTER for databases created before it existed.
ALTER TABLE products ADD COLUMN IF NOT EXISTS image_key TEXT;


-- ----------------------------------------------------------------------------
-- 3. orders
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS orders (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id  INTEGER       NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    status       TEXT          NOT NULL DEFAULT 'PENDING',
    total_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
    created_at   TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    updated_at   TIMESTAMPTZ   NOT NULL DEFAULT NOW(),

    CONSTRAINT orders_status_check
        CHECK (status IN ('PENDING', 'CONFIRMED', 'SHIPPED', 'DELIVERED', 'CANCELLED')),
    CONSTRAINT orders_total_amount_check CHECK (total_amount >= 0),
    -- Target for composite FKs below: lets return_requests prove that the
    -- order really belongs to the customer who is returning it.
    CONSTRAINT orders_id_customer_uniq UNIQUE (id, customer_id)
);

CREATE INDEX IF NOT EXISTS orders_customer_id_idx ON orders (customer_id);
CREATE INDEX IF NOT EXISTS orders_status_idx      ON orders (status);


-- ----------------------------------------------------------------------------
-- 4. order_items
-- unit_price is a snapshot at purchase time, so later product price changes
-- never rewrite history.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS order_items (
    id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id   INTEGER       NOT NULL REFERENCES orders (id)   ON DELETE RESTRICT,
    product_id INTEGER       NOT NULL REFERENCES products (id) ON DELETE RESTRICT,
    quantity   INTEGER       NOT NULL,
    unit_price NUMERIC(12,2) NOT NULL,
    created_at TIMESTAMPTZ   NOT NULL DEFAULT NOW(),

    CONSTRAINT order_items_quantity_check   CHECK (quantity > 0),
    CONSTRAINT order_items_unit_price_check CHECK (unit_price >= 0),
    -- Target for the composite FK from return_requests
    CONSTRAINT order_items_id_order_product_uniq UNIQUE (id, order_id, product_id)
);

CREATE INDEX IF NOT EXISTS order_items_order_id_idx   ON order_items (order_id);
CREATE INDEX IF NOT EXISTS order_items_product_id_idx ON order_items (product_id);


-- ----------------------------------------------------------------------------
-- 5. return_requests  (the central table of ReturnFlow)
--
-- Integrity guarantees via composite foreign keys:
--   (order_id, customer_id)             -> orders      : the order is the customer's own
--   (order_item_id, order_id, product_id) -> order_items : the item belongs to that order
--                                                          and is that product
-- order_id and product_id are therefore intentionally denormalised: they make
-- common queries cheap, and the database guarantees they can never disagree
-- with order_item_id.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS return_requests (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id        INTEGER     NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    order_id           INTEGER     NOT NULL,
    order_item_id      INTEGER     NOT NULL,
    product_id         INTEGER     NOT NULL REFERENCES products (id) ON DELETE RESTRICT,
    reason             TEXT        NOT NULL,
    description        TEXT,
    customer_image_url TEXT,                        -- photo for AI inspection
    status             TEXT        NOT NULL DEFAULT 'RETURN_REQUESTED',
    seller_decision_at TIMESTAMPTZ,                 -- set on SELLER_APPROVED / SELLER_REJECTED
    created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT return_requests_reason_check
        CHECK (reason IN ('DAMAGED', 'WRONG_ITEM', 'SIZE_ISSUE',
                          'NOT_AS_DESCRIBED', 'CHANGED_MIND', 'OTHER')),
    CONSTRAINT return_requests_status_check
        CHECK (status IN ('RETURN_REQUESTED', 'SELLER_APPROVED', 'SELLER_REJECTED',
                          'PICKUP_ASSIGNED', 'PICKED_UP', 'WAREHOUSE_RECEIVED',
                          'INSPECTION', 'INSPECTION_APPROVED', 'INSPECTION_REJECTED',
                          'REFUND_PENDING', 'REFUNDED', 'COMPLETED')),
    CONSTRAINT return_requests_order_customer_fk
        FOREIGN KEY (order_id, customer_id)
        REFERENCES orders (id, customer_id) ON DELETE RESTRICT,
    CONSTRAINT return_requests_order_item_fk
        FOREIGN KEY (order_item_id, order_id, product_id)
        REFERENCES order_items (id, order_id, product_id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS return_requests_customer_id_idx ON return_requests (customer_id);
CREATE INDEX IF NOT EXISTS return_requests_order_id_idx    ON return_requests (order_id);
CREATE INDEX IF NOT EXISTS return_requests_product_id_idx  ON return_requests (product_id);
CREATE INDEX IF NOT EXISTS return_requests_status_idx      ON return_requests (status);
CREATE INDEX IF NOT EXISTS return_requests_created_at_idx  ON return_requests (created_at DESC);
-- Seller dashboard: "returns for my products, by status" joins via product_id
CREATE INDEX IF NOT EXISTS return_requests_product_status_idx ON return_requests (product_id, status);

-- An order item can only be returned once, unless the seller rejected the
-- earlier request (then the customer is allowed to try again).
CREATE UNIQUE INDEX IF NOT EXISTS return_requests_one_active_per_item_idx
    ON return_requests (order_item_id)
    WHERE status <> 'SELLER_REJECTED';


-- ----------------------------------------------------------------------------
-- 6. pickup_assignments
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS pickup_assignments (
    id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    return_request_id INTEGER     NOT NULL REFERENCES return_requests (id) ON DELETE RESTRICT,
    agent_id          INTEGER     NOT NULL REFERENCES users (id)           ON DELETE RESTRICT,
    status            TEXT        NOT NULL DEFAULT 'ASSIGNED',
    assigned_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    picked_up_at      TIMESTAMPTZ,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT pickup_assignments_status_check
        CHECK (status IN ('ASSIGNED', 'ACCEPTED', 'PICKED_UP', 'FAILED', 'CANCELLED')),
    CONSTRAINT pickup_assignments_picked_up_check
        CHECK (status <> 'PICKED_UP' OR picked_up_at IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS pickup_assignments_return_request_id_idx ON pickup_assignments (return_request_id);
CREATE INDEX IF NOT EXISTS pickup_assignments_agent_status_idx      ON pickup_assignments (agent_id, status);

-- At most one live assignment per return. FAILED / CANCELLED rows stay as
-- history, so a failed pickup can be reassigned.
CREATE UNIQUE INDEX IF NOT EXISTS pickup_assignments_one_active_per_return_idx
    ON pickup_assignments (return_request_id)
    WHERE status IN ('ASSIGNED', 'ACCEPTED', 'PICKED_UP');


-- ----------------------------------------------------------------------------
-- 7. inspections
-- The ai_* columns are ADVISORY only; the warehouse employee makes the final
-- decision (status / condition / notes). AI columns are NULL until the AI runs.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS inspections (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    return_request_id  INTEGER     NOT NULL REFERENCES return_requests (id) ON DELETE RESTRICT,
    warehouse_staff_id INTEGER     NOT NULL REFERENCES users (id)           ON DELETE RESTRICT,
    condition          TEXT,                          -- human assessment, NULL until inspected
    ai_product_match   BOOLEAN,                       -- NULL = AI has not run
    ai_damage_detected BOOLEAN,                       -- NULL = AI has not run
    ai_damage_type     TEXT,
    ai_confidence      NUMERIC(4,3),                  -- 0.000 .. 1.000
    ai_result          JSONB,                         -- raw AI response, shape may evolve
    notes              TEXT,
    status             TEXT        NOT NULL DEFAULT 'PENDING',
    created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT inspections_status_check
        CHECK (status IN ('PENDING', 'IN_PROGRESS', 'APPROVED', 'REJECTED', 'MANUAL_REVIEW')),
    CONSTRAINT inspections_condition_check
        CHECK (condition IS NULL OR condition IN
               ('UNOPENED', 'LIKE_NEW', 'USED', 'DAMAGED', 'WRONG_ITEM')),
    CONSTRAINT inspections_ai_confidence_check
        CHECK (ai_confidence IS NULL OR (ai_confidence >= 0 AND ai_confidence <= 1))
);

-- One inspection per return request
CREATE UNIQUE INDEX IF NOT EXISTS inspections_return_request_id_uniq ON inspections (return_request_id);
CREATE INDEX IF NOT EXISTS inspections_warehouse_staff_id_idx ON inspections (warehouse_staff_id);
CREATE INDEX IF NOT EXISTS inspections_status_idx             ON inspections (status);
CREATE INDEX IF NOT EXISTS inspections_ai_result_gin_idx      ON inspections USING GIN (ai_result);


-- ----------------------------------------------------------------------------
-- 8. refunds
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS refunds (
    id                    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    return_request_id     INTEGER       NOT NULL REFERENCES return_requests (id) ON DELETE RESTRICT,
    customer_id           INTEGER       NOT NULL REFERENCES users (id)           ON DELETE RESTRICT,
    amount                NUMERIC(12,2) NOT NULL,
    status                TEXT          NOT NULL DEFAULT 'PENDING',
    transaction_reference TEXT,
    processed_at          TIMESTAMPTZ,
    created_at            TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    updated_at            TIMESTAMPTZ   NOT NULL DEFAULT NOW(),

    CONSTRAINT refunds_amount_check CHECK (amount >= 0),
    CONSTRAINT refunds_status_check
        CHECK (status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'CANCELLED')),
    CONSTRAINT refunds_completed_check
        CHECK (status <> 'COMPLETED' OR processed_at IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS refunds_return_request_id_idx ON refunds (return_request_id);
CREATE INDEX IF NOT EXISTS refunds_customer_id_idx       ON refunds (customer_id);
CREATE INDEX IF NOT EXISTS refunds_status_idx            ON refunds (status);

-- transaction_reference is unique when present (multiple NULLs are allowed)
CREATE UNIQUE INDEX IF NOT EXISTS refunds_transaction_reference_uniq
    ON refunds (transaction_reference)
    WHERE transaction_reference IS NOT NULL;

-- A return can never get two live refunds (open or completed). FAILED /
-- CANCELLED refunds stay as history, so a failed refund can be retried.
CREATE UNIQUE INDEX IF NOT EXISTS refunds_one_live_per_return_idx
    ON refunds (return_request_id)
    WHERE status IN ('PENDING', 'PROCESSING', 'COMPLETED');


-- ----------------------------------------------------------------------------
-- return_images: photos a customer attaches to a return request (at most 2 per return, enforced by the backend).
-- Only a reference to the object in the PRIVATE S3 bucket is stored: never the image itself, never a URL.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS return_images (
    id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    return_request_id INTEGER     NOT NULL REFERENCES return_requests (id) ON DELETE CASCADE,
    image_key         TEXT        NOT NULL,              -- S3 object key, e.g. returns/12/<uuid>.jpg
    image_type        TEXT        NOT NULL,              -- MIME type
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT return_images_type_check CHECK (image_type IN ('image/jpeg', 'image/png', 'image/webp'))
);

CREATE INDEX IF NOT EXISTS return_images_return_request_id_idx ON return_images (return_request_id);
CREATE UNIQUE INDEX IF NOT EXISTS return_images_image_key_uniq ON return_images (image_key);


-- ----------------------------------------------------------------------------
-- ai_assessments: the advisory AI comparison of a warehouse inspection (reference image vs the customer's photos).
-- One row per inspection; a retry reuses the row and raises `attempts`. The validated result is stored as JSON;
-- no images are stored here. It never changes the inspection or the return: staff still decide.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ai_assessments (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    inspection_id INTEGER     NOT NULL REFERENCES inspections (id) ON DELETE CASCADE,
    status        TEXT        NOT NULL DEFAULT 'RUNNING',
    model         TEXT        NOT NULL,
    provider      TEXT        NOT NULL,
    result        JSONB,                              -- validated assessment, only when COMPLETED
    error_code    TEXT,                               -- short safe code, only when FAILED
    attempts      INTEGER     NOT NULL DEFAULT 1,     -- also the token that stops a stale attempt overwriting a newer one
    started_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at  TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT ai_assessments_status_check CHECK (status IN ('RUNNING', 'COMPLETED', 'FAILED')),
    CONSTRAINT ai_assessments_inspection_uniq UNIQUE (inspection_id),
    CONSTRAINT ai_assessments_result_check CHECK (status <> 'COMPLETED' OR result IS NOT NULL)
);


-- ----------------------------------------------------------------------------
-- invitations: how SELLER / PICKUP_AGENT / WAREHOUSE accounts come to exist.
-- An admin invites an email for a role; the invited person sets a name and password
-- through a one-time link. Only the SHA-256 hash of the token is stored. The role of
-- the new account is copied from this row, never from the browser.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS invitations (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email       TEXT        NOT NULL,              -- normalized: trimmed + lower-case
    role        TEXT        NOT NULL,
    token_hash  TEXT        NOT NULL,              -- sha256 hex of the emailed token
    invited_by  INTEGER     NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    status      TEXT        NOT NULL DEFAULT 'PENDING',
    expires_at  TIMESTAMPTZ NOT NULL,
    accepted_at TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT invitations_role_check   CHECK (role IN ('SELLER', 'PICKUP_AGENT', 'WAREHOUSE')),
    CONSTRAINT invitations_status_check CHECK (status IN ('PENDING', 'ACCEPTED', 'EXPIRED', 'CANCELLED')),
    CONSTRAINT invitations_email_lower  CHECK (email = LOWER(email))
);

CREATE UNIQUE INDEX IF NOT EXISTS invitations_token_hash_uniq ON invitations (token_hash);
-- One open invitation per email at a time (resend replaces the token instead of adding a row)
CREATE UNIQUE INDEX IF NOT EXISTS invitations_one_pending_per_email_idx ON invitations (email) WHERE status = 'PENDING';
CREATE INDEX IF NOT EXISTS invitations_created_idx ON invitations (created_at DESC, id DESC);


-- ----------------------------------------------------------------------------
-- updated_at triggers (tables that have an updated_at column)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
    t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY['users', 'products', 'orders', 'return_requests',
                             'pickup_assignments', 'inspections', 'refunds', 'invitations', 'ai_assessments']
    LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I', t || '_set_updated_at', t);
        EXECUTE format(
            'CREATE TRIGGER %I BEFORE UPDATE ON %I
             FOR EACH ROW EXECUTE FUNCTION set_updated_at()',
            t || '_set_updated_at', t);
    END LOOP;
END $$;
